using Habitica.Application.Workspace;
using Bunit;
using Habitica.Domain.Workspace;
using Habitica.WebApp.Components;
using Habitica.WebApp.State;
using Microsoft.Extensions.DependencyInjection;
using MudBlazor.Services;
namespace Habitica.WebApp.Tests.Workspace;
public sealed class RelativeSavedListPanelTests:BunitContext
{
    private sealed class Clock:TimeProvider{public DateTimeOffset Instant=DateTimeOffset.Parse("2026-11-03T12:00:00Z");public override DateTimeOffset GetUtcNow()=>Instant;}
    private async Task<(TodoOrganizationFixture F,Clock Clock)> Setup(WorkspaceDocument? doc=null)
    {
        JSInterop.Mode=JSRuntimeMode.Loose;JSInterop.SetupModule("./js/field-focus.js").SetupVoid("revealFocusedElement", _=>true).SetVoidResult();Services.AddMudServices();var f=new TodoOrganizationFixture();await f.Load(true,doc??new(){Id=Guid.NewGuid(),Revision=10});var clock=new Clock();Services.AddSingleton<IAppSessionController>(f.Task.Session);Services.AddSingleton<IWorkspaceCloudClient>(f.Task.Client);Services.AddSingleton(f.Task.Database);Services.AddSingleton(f.Task.Controller);Services.AddSingleton(f.Organization);Services.AddSingleton(f.Todo);Services.AddSingleton<TodoTaskDraftStore>();Services.AddSingleton<TimeProvider>(clock);return(f,clock);
    }
    private static void Save(string name,string markup,string state)=>Qualification.PageLayoutEvidence.Save(name,markup,"/todo/lists",state,["form","actions","confirmation","disabled-controls","error","navigation"],nameof(RelativeSavedListPanelTests));
    [Fact]public async Task Relative_editor_requires_explicit_timezone_and_clears_conflicting_fixed_dates_only_on_request()
    {
        var(f,_)=await Setup();using var owned=f;var cut=Render<TodoSavedListPanel>();cut.Find("[data-testid=saved-list-name]").Input("Today and overdue");cut.Find("[data-testid=saved-list-planned-from]").Change("2026-11-01");cut.Find("[data-testid=saved-list-planned-relative]").Change("Today");Assert.Contains("conflicting fixed planned",cut.Markup);Assert.Equal("2026-11-01",cut.Find("[data-testid=saved-list-planned-from]").GetAttribute("value"));cut.Find("form").Submit();Assert.Empty(f.Api.Requests);Save("relative-list-conflict",cut.Markup,"explicit-absolute-relative-conflict");cut.Find("[data-testid=saved-list-clear-planned]").Click();Assert.True(cut.Find("[data-testid=saved-list-planned-from]").HasAttribute("disabled"));cut.Find("form").Submit();Assert.Empty(f.Api.Requests);cut.Find("[data-testid=saved-list-timezone]").Change("UTC");cut.Find("[data-testid=saved-list-deadline-relative]").Change("BeforeToday");Save("relative-list-editor",cut.Markup,"explicit-separate-date-presets-and-timezone");cut.Find("form").Submit();cut.WaitForAssertion(()=>Assert.NotNull(f.Organization.Preview));Assert.Contains("2026-11-03 through 2026-11-03",cut.Markup);Assert.Contains("Unbounded through 2026-11-02",cut.Markup);Save("relative-list-review",cut.Markup,"interpreted-independent-date-bounds");cut.Find("[data-testid=saved-list-confirm]").Click();cut.WaitForAssertion(()=>Assert.NotNull(f.Organization.LastReceipt));Assert.Empty(f.Task.Client.State.Document.Tasks);Assert.Single(f.Task.Client.State.Document.SavedTaskViews!);Assert.Equal(WorkspaceRelativeDatePreset.Today,f.Task.Client.State.Document.SavedTaskViews![0].Query.Filter.PlannedRelative);Assert.Empty(f.Task.Client.State.Commands);Save("relative-list-saved",cut.Markup,"saved-intent-without-task-duplication");
    }
    [Fact]public async Task Midnight_continuation_refuses_mixed_pages_and_explicit_restart_recomputes_results_without_writes()
    {
        var created=DateTimeOffset.Parse("2026-11-01T00:00:00Z");var tasks=Enumerable.Range(0,25).Select(i=>new CompanionTask(Guid.NewGuid(),1,"Task "+i,CompanionTaskKind.Todo,CompanionTaskState.Active,CompanionPriority.Normal,created,created,PlannedDate:new(2026,11,3))).ToArray();var view=new WorkspaceSavedTaskView(Guid.NewGuid(),1,"Today",new(WorkspaceSavedTaskSource.Tasks,new(PlannedRelative:WorkspaceRelativeDatePreset.Today),"UTC"));var(f,clock)=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=tasks,SavedTaskViews=[view]});using var owned=f;var cut=Render<TodoSavedListPanel>();cut.Find($"[data-testid=saved-list-open-{view.Id:D}]").Click();Assert.Equal(20,cut.FindAll("[data-testid^=saved-list-task-]").Count);Save("relative-list-page",cut.Markup,"guarded-first-page-as-of-context");clock.Instant=clock.Instant.AddDays(1);cut.FindAll("button").Single(b=>b.TextContent.Contains("Next matching tasks")).Click();Assert.Contains("local evaluation day changed",cut.Markup);Assert.Empty(cut.FindAll("[data-testid^=saved-list-task-]"));Save("relative-list-stale-day",cut.Markup,"day-changed-no-fallback-or-mixed-page");cut.Find("[data-testid=saved-list-restart-day]").Click();Assert.Contains("0 matching",cut.Markup);Assert.Contains("2026-11-04",cut.Find("[data-testid=saved-relative-evaluation]").TextContent);Assert.Empty(f.Api.Requests);Assert.Equal(25,f.Task.Client.State.Document.Tasks.Count);Save("relative-list-restarted",cut.Markup,"explicit-new-day-empty-result");
    }
    [Fact]public async Task Unsupported_timezone_stays_explicitly_unavailable_and_account_change_hides_private_list_data()
    {
        var view=new WorkspaceSavedTaskView(Guid.NewGuid(),1,new string('W',150)+" private relative list",new(WorkspaceSavedTaskSource.Tasks,new(DeadlineRelative:WorkspaceRelativeDatePreset.NoDate),"Missing/Historical"));var(f,_)=await Setup(new(){Id=Guid.NewGuid(),Revision=10,SavedTaskViews=[view]});using var owned=f;var cut=Render<TodoSavedListPanel>();cut.Find($"[data-testid=saved-list-open-{view.Id:D}]").Click();Assert.Contains("timezone or date bounds are unavailable",cut.Markup);Assert.Empty(cut.FindAll("[data-testid=saved-list-count]"));Save("relative-list-unavailable",cut.Markup,"unavailable-stored-timezone-no-empty-success");f.Task.Session.SetState(f.Task.Session.State with{UserId=Guid.NewGuid().ToString("D")});cut.WaitForAssertion(()=>Assert.DoesNotContain(view.Name,cut.Markup));Assert.Empty(f.Api.Requests);Save("relative-list-account",cut.Markup,"account-change-clears-private-selected-definition");
    }
}
